#!/usr/bin/env bash
set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
suite_dir="$(cd "$script_dir/.." && pwd)"
source_dir="$suite_dir/products/spring"
: "${BENCH_PRODUCT_DIR:?BENCH_PRODUCT_DIR is required}"
state="$BENCH_PRODUCT_DIR/adapter.state"

die() {
  printf 'spring adapter: %s\n' "$*" >&2
  exit 1
}

load_state() {
  [[ -f "$state" ]] || die "state is missing; run prepare first"
  # This file contains paths and unit names generated by this adapter.
  source "$state"
}

unit_pid() {
  systemctl --user show "$1" -p MainPID --value 2>/dev/null \
    | awk '$1 ~ /^[0-9]+$/ && $1 > 0 {print $1}'
}

wait_http() {
  local url="$1" code
  for _ in {1..400}; do
    code="$(curl -sS -o /dev/null -w '%{http_code}' --max-time 1 "$url" 2>/dev/null || true)"
    [[ "$code" == 2* ]] && return 0
    sleep 0.1
  done
  return 1
}

apply_route() {
  local id="$1" file="$routes_dir/$1.json" output="$2" code
  code="$(curl -sS --max-time 10 -o "$output" -w '%{http_code}' \
    -X POST -H 'Content-Type: application/json' --data-binary "@$file" \
    "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/gateway/routes/$id" || true)"
  [[ "$code" == 200 || "$code" == 201 ]] \
    || die "Actuator rejected route $id with HTTP $code"
}

delete_route() {
  local id="$1" output="$2" code
  code="$(curl -sS --max-time 10 -o "$output" -w '%{http_code}' -X DELETE \
    "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/gateway/routes/$id" || true)"
  [[ "$code" == 200 || "$code" == 404 ]] \
    || die "Actuator failed to delete route $id with HTTP $code"
}

refresh_routes() {
  local output="$1" code
  code="$(curl -sS --max-time 10 -o "$output" -w '%{http_code}' -X POST \
    "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/gateway/refresh" || true)"
  [[ "$code" == 200 ]] || die "Actuator route refresh returned HTTP $code"
}

probe_version() {
  local expected="$1" output="$2" code
  for _ in {1..20}; do
    code="$(curl -sS --max-time 3 -o "$output" -w '%{http_code}' \
      -H "Authorization: Bearer $BENCH_VALID_TOKEN" \
      -H 'X-Forwarded-For: 198.18.81.81' -H 'X-Request-ID: spring-config-probe' \
      "$BENCH_GATEWAY_URL/api/items" || true)"
    if [[ "$code" == 200 ]] && jq -e --arg expected "$expected" \
      '.headers["x-bench-version"] == $expected' "$output" >/dev/null 2>&1; then
      return 0
    fi
    sleep 0.1
  done
  die "version probe did not observe $expected"
}

probe_ban_status() {
  local expected="$1" output="$2" code
  code="$(curl -sS --max-time 5 -o "$output" -w '%{http_code}' \
    -H "Authorization: Bearer $BENCH_VALID_TOKEN" \
    -H "X-Forwarded-For: $BENCH_BANNED_IP" -H 'X-Request-ID: spring-ban-probe' \
    "$BENCH_GATEWAY_URL/probe/ban" || true)"
  [[ "$code" == "$expected" ]] || die "ban probe expected HTTP $expected, got $code"
}

snapshot() {
  local label="$1" out="$BENCH_PRODUCT_DIR/snapshots/$1"
  mkdir -p "$out"
  curl -sS --max-time 3 "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/health" \
    >"$out/health.json" || true
  curl -sS --max-time 3 "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/gateway/routes" \
    >"$out/routes.json" || true
  curl -sS --max-time 3 "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/gateway/routedefinitions" \
    >"$out/route-definitions.json" || true
  curl -sS --max-time 3 "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/prometheus" \
    >"$out/metrics.prom" || true
  systemctl --user show "$slice.slice" -p CPUQuotaPerSecUSec -p MemoryMax -p AllowedCPUs \
    -p ControlGroup >"$out/resource-limits.txt" 2>&1 || true
  systemctl --user show "$unit" -p Id -p MainPID -p ExecStart \
    >"$out/service.txt" 2>&1 || true
}

action="${1:-}"
case "$action" in
  preflight)
    for command in java mvn curl jq python3 systemd-run systemctl sha256sum; do
      command -v "$command" >/dev/null || die "missing command $command"
    done
    [[ "$(java -version 2>&1 | head -1)" == *'21.'* ]] || die "Java 21 is required"
    systemctl --user is-system-running >/dev/null 2>&1 || die "user systemd is not running"
    ;;
  prepare)
    case "${BENCH_UPSTREAM_COUNT:-5}" in 2|5) ;; *) die "BENCH_UPSTREAM_COUNT must be 2 or 5" ;; esac
    for name in BENCH_GATEWAY_PORT BENCH_UPSTREAM_A_PORT BENCH_UPSTREAM_B_PORT \
      BENCH_UPSTREAM_C_PORT BENCH_UPSTREAM_D_PORT BENCH_UPSTREAM_E_PORT \
      BENCH_JWT_SECRET BENCH_JWT_ISSUER BENCH_BANNED_IP BENCH_RATE_CAPACITY \
      BENCH_RATE_REFILL BENCH_MEMORY_BYTES BENCH_SPRING_XMX_MB BENCH_SPRING_DIRECT_MB; do
      [[ -n "${!name:-}" ]] || die "$name is required"
    done
    runtime="$BENCH_PRODUCT_DIR/runtime"
    routes_dir="$BENCH_PRODUCT_DIR/configs/routes"
    unit_token="$(printf '%s' "$BENCH_PRODUCT_DIR" | sha256sum | cut -c1-12)"
    slice="benchcmp$unit_token"
    unit="benchcmp$unit_token-spring.service"
    mkdir -p "$runtime" "$routes_dir" "$BENCH_PRODUCT_DIR/configs/source" \
      "$BENCH_PRODUCT_DIR/logs" "$BENCH_PRODUCT_DIR/snapshots"
    mvn -q -f "$source_dir/pom.xml" -DskipTests clean package
    jar_source="$(/usr/bin/find "$source_dir/target" -maxdepth 1 -type f -name '*.jar' ! -name '*.original' | head -1)"
    [[ -n "$jar_source" ]] || die "Spring executable jar was not produced"
    cp "$jar_source" "$runtime/spring-gateway.jar"
    cp "$source_dir/pom.xml" "$BENCH_PRODUCT_DIR/configs/source/pom.xml"
    cp "$source_dir/render_routes.py" "$BENCH_PRODUCT_DIR/configs/source/render_routes.py"
    cp -a "$source_dir/src" "$BENCH_PRODUCT_DIR/configs/source/src"
    mvn -q -f "$source_dir/pom.xml" dependency:tree \
      -DoutputFile="$BENCH_PRODUCT_DIR/configs/source/dependency-tree.txt"
    cp "$source_dir/application.yml.in" "$runtime/application.yml"
    sed -i \
      -e "s|@GATEWAY_PORT@|$BENCH_GATEWAY_PORT|g" \
      -e "s|@UPSTREAM_A_PORT@|$BENCH_UPSTREAM_A_PORT|g" \
      -e "s|@UPSTREAM_B_PORT@|$BENCH_UPSTREAM_B_PORT|g" \
      -e "s|@UPSTREAM_C_PORT@|$BENCH_UPSTREAM_C_PORT|g" \
      -e "s|@UPSTREAM_D_PORT@|$BENCH_UPSTREAM_D_PORT|g" \
      -e "s|@UPSTREAM_E_PORT@|$BENCH_UPSTREAM_E_PORT|g" \
      -e "s|@JWT_SECRET@|$BENCH_JWT_SECRET|g" \
      -e "s|@JWT_ISSUER@|$BENCH_JWT_ISSUER|g" \
      -e "s|@BANNED_IP@|$BENCH_BANNED_IP|g" \
      -e "s|@RATE_CAPACITY@|$BENCH_RATE_CAPACITY|g" \
      -e "s|@RATE_REFILL@|$BENCH_RATE_REFILL|g" \
      -e "s|@LOG_FILE@|$runtime/spring.log|g" \
      "$runtime/application.yml"
    python3 - "$runtime/application.yml" "${BENCH_UPSTREAM_COUNT:-5}" \
      "$BENCH_UPSTREAM_A_PORT" "$BENCH_UPSTREAM_B_PORT" "$BENCH_UPSTREAM_C_PORT" \
      "$BENCH_UPSTREAM_D_PORT" "$BENCH_UPSTREAM_E_PORT" <<'PY'
import pathlib, sys
path = pathlib.Path(sys.argv[1])
count = int(sys.argv[2])
ports = list(map(int, sys.argv[3:8]))[:count]
weights = [1, 1] if count == 2 else [5, 3, 2, 1, 1]
lines = []
for name, port, weight in zip("ABCDE", ports, weights):
    lines.extend([
        f"              - instance-id: {name}",
        f"                uri: http://127.0.0.1:{port}",
        f"                metadata: {{weight: {weight}}}",
    ])
text = path.read_text(encoding="utf-8").replace("@UPSTREAM_INSTANCES@", "\n".join(lines))
path.write_text(text, encoding="utf-8")
PY
    python3 "$source_dir/render_routes.py" --output "$routes_dir" \
      --upstream-a "127.0.0.1:$BENCH_UPSTREAM_A_PORT" --banned-ip "$BENCH_BANNED_IP"
    cp "$runtime/application.yml" "$BENCH_PRODUCT_DIR/configs/application.yml"
    sha256sum "$runtime/spring-gateway.jar" "$routes_dir"/*.json \
      >"$BENCH_PRODUCT_DIR/configs/artifacts.sha256"
    cat >"$BENCH_PRODUCT_DIR/capabilities.json" <<'JSON'
{
  "http_proxy": "PASS-OFFICIAL-SCG",
  "websocket": "PASS-OFFICIAL-SCG",
  "metrics": "PASS-OFFICIAL-ACTUATOR-MICROMETER",
  "routing": "PASS-OFFICIAL-SCG",
  "jwt": "PASS-OFFICIAL-SPRING-SECURITY-RESOURCE-SERVER",
  "waf": "PARTIAL-OFFICIAL-STRICT-FIREWALL-CUSTOM-RULES",
  "ip_ban": "PARTIAL-OFFICIAL-ROUTE-POLICY-NO-TTL-OR-SYNC",
  "rate_limit": "PASS-OFFICIAL-SCG-BUCKET4J-CAFFEINE",
  "weighted_load_balancing": "PASS-OFFICIAL-SPRING-CLOUD-LOADBALANCER",
  "least_connections": "UNSUPPORTED-BUILTIN",
  "active_health_check": "PASS-OFFICIAL-SPRING-CLOUD-LOADBALANCER",
  "circuit_breaker": "PASS-OFFICIAL-SPRING-CLOUD-CIRCUITBREAKER-RESILIENCE4J",
  "endpoint_circuit_breaker": "UNSUPPORTED-BUILTIN",
  "connection_pool": "PASS-OFFICIAL-REACTOR-NETTY",
  "hot_reload": "PASS-OFFICIAL-ACTUATOR-ROUTE-DEFINITION",
  "high_precision_trace_toggle": "UNSUPPORTED",
  "external_control_plane": "NOT-APPLICABLE"
}
JSON
    cat >"$state" <<EOF
runtime=$(printf '%q' "$runtime")
routes_dir=$(printf '%q' "$routes_dir")
slice=$(printf '%q' "$slice")
unit=$(printf '%q' "$unit")
EOF
    ;;
  start)
    load_state
    systemctl --user set-property --runtime "$slice.slice" \
      CPUQuota="${BENCH_CPU_QUOTA_PERCENT:-100}%" \
      MemoryMax="$BENCH_MEMORY_BYTES" AllowedCPUs="${BENCH_TARGET_CPU:-2}"
    systemd-run --user --quiet --collect --unit "$unit" --slice "$slice" \
      --working-directory "$runtime" \
      --property "StandardOutput=append:$BENCH_PRODUCT_DIR/logs/spring-process.log" \
      --property "StandardError=append:$BENCH_PRODUCT_DIR/logs/spring-process.log" \
      /usr/bin/java -Xms64m -Xmx"${BENCH_SPRING_XMX_MB}"m \
      -XX:MaxDirectMemorySize="${BENCH_SPRING_DIRECT_MB}"m \
      -Dreactor.netty.ioWorkerCount="${BENCH_GATEWAY_WORKERS:-1}" \
      -jar "$runtime/spring-gateway.jar" --spring.config.location="$runtime/application.yml"
    wait_http "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/health" \
      || die "Spring gateway did not become ready"
    if [[ "${BENCH_CAPACITY_MODE:-0}" == 1 ]]; then
      apply_route spring-capacity-ip-policy \
        "$BENCH_PRODUCT_DIR/snapshots/capacity-ip-policy-route.json"
      refresh_routes "$BENCH_PRODUCT_DIR/snapshots/capacity-ip-policy-refresh.json"
    fi
    systemctl --user show "$slice.slice" -p ControlGroup --value >"$BENCH_PRODUCT_DIR/cgroup.path"
    snapshot started
    ;;
  ready)
    load_state
    wait_http "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/health"
    ;;
  pids)
    load_state
    unit_pid "$unit"
    ;;
  reload-valid)
    load_state
    mkdir -p "$BENCH_PRODUCT_DIR/snapshots/reload-valid-routes"
    for id in spring-v2-api spring-v2-probes spring-v2-exact spring-v2-route spring-v2-ban spring-v2-ws; do
      apply_route "$id" "$BENCH_PRODUCT_DIR/snapshots/reload-valid-routes/$id.json"
    done
    refresh_routes "$BENCH_PRODUCT_DIR/snapshots/reload-valid-refresh.json"
    probe_version v2 "$BENCH_PRODUCT_DIR/snapshots/reload-valid-probe.json"
    snapshot reload-valid
    ;;
  reload-invalid)
    load_state
    code="$(curl -sS --max-time 10 -o "$BENCH_PRODUCT_DIR/snapshots/reload-invalid.txt" \
      -w '%{http_code}' -X POST -H 'Content-Type: application/json' \
      --data-binary "@$routes_dir/spring-invalid-route.json" \
      "http://127.0.0.1:$BENCH_GATEWAY_PORT/actuator/gateway/routes/spring-invalid-route" || true)"
    [[ "$code" == 400 ]] || die "invalid RouteDefinition returned HTTP $code"
    delete_route spring-invalid-route "$BENCH_PRODUCT_DIR/snapshots/reload-invalid-cleanup.json"
    refresh_routes "$BENCH_PRODUCT_DIR/snapshots/reload-invalid-refresh.json"
    probe_version v2 "$BENCH_PRODUCT_DIR/snapshots/reload-invalid-probe.json"
    snapshot reload-invalid
    ;;
  restart-control)
    load_state
    printf '{"external_control_plane":false,"status":"NOT-APPLICABLE"}\n' \
      >"$BENCH_PRODUCT_DIR/snapshots/control-plane-not-applicable.json"
    snapshot control-restarted
    ;;
  security-seed)
    load_state
    apply_route spring-dynamic-ban "$BENCH_PRODUCT_DIR/snapshots/security-seed-route.json"
    refresh_routes "$BENCH_PRODUCT_DIR/snapshots/security-seed-refresh.json"
    probe_ban_status 403 "$BENCH_PRODUCT_DIR/snapshots/security-seed-probe.json"
    ;;
  security-unban)
    load_state
    delete_route spring-dynamic-ban "$BENCH_PRODUCT_DIR/snapshots/security-unban-route.json"
    refresh_routes "$BENCH_PRODUCT_DIR/snapshots/security-unban-refresh.json"
    probe_ban_status 200 "$BENCH_PRODUCT_DIR/snapshots/security-unban-probe.json"
    ;;
  trace-on)
    load_state
    printf '{"supported":false,"status":"UNSUPPORTED","reason":"no equivalent runtime high-precision trace toggle"}\n' \
      >"$BENCH_PRODUCT_DIR/snapshots/trace-on.json"
    snapshot trace-on
    ;;
  trace-off)
    load_state
    printf '{"supported":false,"status":"UNSUPPORTED"}\n' \
      >"$BENCH_PRODUCT_DIR/snapshots/trace-off.json"
    snapshot trace-off
    ;;
  observe-probe)
    load_state
    code="$(curl -sS --max-time 3 -o "$BENCH_PRODUCT_DIR/snapshots/observe-body.json" \
      -D "$BENCH_PRODUCT_DIR/snapshots/observe-headers.txt" -w '%{http_code}' \
      -H "Authorization: Bearer $BENCH_VALID_TOKEN" \
      -H 'X-Forwarded-For: 198.18.80.80' -H 'X-Request-ID: bench-observe-fixed' \
      "$BENCH_GATEWAY_URL/probe/observe")"
    [[ "$code" == 200 ]] || die "observation probe returned HTTP $code"
    ;;
  observe-verify)
    load_state
    for _ in {1..30}; do
      zgrep -h -F 'request_id=bench-observe-fixed' "$runtime"/spring.log* \
        >"$BENCH_PRODUCT_DIR/snapshots/observe-access.log" 2>/dev/null && break
      sleep 0.1
    done
    [[ -s "$BENCH_PRODUCT_DIR/snapshots/observe-access.log" ]] \
      || die "request id missing from Spring access log"
    printf 'UNSUPPORTED: no equivalent runtime high-precision trace toggle\n' \
      >"$BENCH_PRODUCT_DIR/snapshots/observe-trace.txt"
    snapshot observe-verified
    ;;
  log-rotate)
    load_state
    for log in "$runtime/spring.log" "$BENCH_PRODUCT_DIR/logs/spring-process.log"; do
      if [[ -f "$log" ]]; then
        cp "$log" "$log.1"
        : >"$log"
      fi
    done
    snapshot log-rotated
    ;;
  snapshot*)
    load_state
    snapshot "$action"
    ;;
  stop)
    if [[ -f "$state" ]]; then
      load_state
      systemctl --user stop "$unit" >/dev/null 2>&1 || true
      systemctl --user stop "$slice.slice" >/dev/null 2>&1 || true
      systemctl --user reset-failed "$unit" "$slice.slice" >/dev/null 2>&1 || true
    fi
    ;;
  *)
    die "unknown action: $action"
    ;;
esac
